Update_Table_Order.syntax_text:
private void Update_Table_Order(int itemId, string invGlobalId)
        {
            try
            {
                if (conn.State != System.Data.ConnectionState.Open)
                    conn.Open();

                var cmd = new SqlCommand(
                    "UPDATE Table_Order SET isNew=0 " +
                    "WHERE ItemId=@ItemId AND InvGlobalID=@InvGlobalID",
                    conn);
                cmd.Parameters.AddWithValue("@ItemId", itemId);
                cmd.Parameters.AddWithValue("@InvGlobalID", invGlobalId);
                cmd.ExecuteNonQuery();
            }
            catch { }
        }

Window_KeyDown.syntax_text:
private void Window_KeyDown(object sender, KeyEventArgs e)
        {
            // Alt+B → Barcode
            if (Keyboard.Modifiers == ModifierKeys.Alt)
            {
                if (e.Key == Key.B)
                {
                    e.Handled = true;
                    txtBarcode.Focus();
                    return;
                }
                if (e.Key == Key.G)
                {
                    glassesOptions();
                    return;
                }
            }

            switch (e.Key)
            {
                case Key.F1:
                    addNewItem();
                    e.Handled = true;
                    break;
                case Key.F2:
                    quantityEdit();
                    e.Handled = true;
                    break;
                case Key.F3:
                    priceEdit();
                    e.Handled = true;
                    break;
                case Key.F4:
                    if (GridControl1.SelectedItem is InvoiceItem si4)
                        ShowItemUnit(si4.ItemId, si4.ItemRowIndex);
                    e.Handled = true;
                    break;
                case Key.F5:
                    deleteRow();
                    e.Handled = true;
                    break;
                case Key.F6:
                    btnPay_Click(null, null);
                    e.Handled = true;
                    break;
                case Key.F7:
                    btnHoldOrd_Click(null, null);
                    e.Handled = true;
                    break;
                case Key.F8:
                    DeleteInv();
                    e.Handled = true;
                    break;
                case Key.F9:
                    btnCloseDay_Click(null, null);
                    e.Handled = true;
                    break;
                case Key.F12:
                    btnNew_Click(null, null);
                    e.Handled = true;
                    break;
                case Key.Return:
                    if (Keyboard.FocusedElement is TextBox tb &&
                        tb.Name == "txtBarcode" &&
                        !string.IsNullOrWhiteSpace(txtBarcode.Text) &&
                        txtBarcode.Text != "بحث باركود")
                    {
                        ReadBarcode(txtBarcode.Text.Trim(), false);
                        txtBarcode.Text = "";
                        e.Handled = true;
                    }
                    break;
                case Key.OemPipe:
                    btnMunalBarcode_Click(null, null);
                    e.Handled = true;
                    break;
            }
        }

conditions.consequence:
{
