Window_KeyDown.syntax_text:
private void Window_KeyDown(object sender, KeyEventArgs e)
        {
            // Alt+B → Focus Barcode
            if (Keyboard.Modifiers == ModifierKeys.Alt && e.Key == Key.B)
            {
                e.Handled = true;
                txtBarcode.Focus();
            }

            // Alt+G → Glasses
            if (Keyboard.Modifiers == ModifierKeys.Alt && e.Key == Key.G)
            {
                glassesOptions();
            }

            // F1 → Add Item
            if (e.Key == Key.F1)
                addNewItem();

            // Enter on Barcode
            if (e.Key == Key.Return)
            {
                if (txtBarcode.IsFocused)
                {
                    ReadBarcode(txtBarcode.Text, false);
                    txtBarcode.Text = "";
                }
                if (txtSrchSerialNo.IsFocused)
                {
                    SearchBySerialNo(txtSrchSerialNo.Text.Trim());
                    txtSrchSerialNo.Text = "";
                }
            }

            // F5 → New
            if (e.Key == Key.F5)
            {
                btnNew_Click(null, null);
                e.Handled = true;
            }

            // F6 → Save
            if (e.Key == Key.F6)
                ValidateInvoice();

            // F7 → Print
            if (e.Key == Key.F7)
            {
                btnPrint_Click(null, null);
                e.Handled = true;
            }

            // F8 → View
            if (e.Key == Key.F8)
            {
                btnView_Click(null, null);
                e.Handled = true;
            }

            // F9 → Delete
            if (e.Key == Key.F9)
            {
                btnDelete_Click(null, null);
                e.Handled = true;
            }
        }

