                    }
                    else
                        SaveGlobalIDOffLine(_invoic.InvGlobalID, _invoic.EntryGlobalID);
                }
            }
            catch (Exception ex)
            {
                ShowError("خطأ أثناء الحفظ والطباعة", ex);
            }
        }

