public static string InsertInv = "insert into Inv(InvGlobalID,proc_type,id,date,inv_type,OrderType,safe,stock,cust_id,sales_emp,InvTotal,AdditionsTot,Insurance,tot_net,paid,minus,EntryID,Reff_No,Reff_date,branch,IS_Buy,IS_Deleted,salesman,tax,pay_type,bank,cash,visa,notes,InvProfit,Sync,ExtraVAT,AdditionalCost,InvoiceStatus,PriceIncVAT,PaymentStatus,InvCombinedId,ItemsDiscount,InvCost,FreeVATSales,InvSum,VATPercent,CurrencyCode,CloudID,CashCustomerName,CashCustomerMobile,QRCode,InvoiceHash,UUID,ZatcaSent,TotalWithholdingTax,TableNo,Balance_previews)values(@InvGlobalID,@proc_type,@id,@date,@inv_type,@OrderType,@safe,@stock,@cust_id,@sales_emp,@InvTotal,@AdditionsTot,@Insurance,@tot_net,@paid,@minus,@EntryID,@Reff_No,@Reff_date,@branch,@IS_Buy,@IS_Deleted,@salesman,@tax,@pay_type,@bank,@cash,@visa,@notes,@InvProfit,@Sync,@ExtraVAT,@AdditionalCost,@InvoiceStatus,@PriceIncVAT,@PaymentStatus,@InvCombinedId,@ItemsDiscount,@InvCost,@FreeVATSales,@InvSum,@VATPercent,@CurrencyCode,@CloudID,@CashCustomerName,@CashCustomerMobile,@QRCode,@InvoiceHash,@UUID,@ZatcaSent,@TotalWithholdingTax,@TableNo,@Balance_previews)";

public static string UpdateInv = " update Inv set id=@id ,proc_type=@proc_type, date=@date ,inv_type=@inv_type ,OrderType=@OrderType,safe=@safe ,stock=@stock ,\r\n                              cust_id=@cust_id ,sales_emp=@sales_emp ,InvTotal=@InvTotal ,AdditionsTot=@AdditionsTot,Insurance=@Insurance,tot_net=@tot_net,minus=@minus,Reff_No=@Reff_No,Reff_date=@Reff_date, IS_Deleted=@IS_Deleted,salesman=@salesman, tax=@tax, pay_type=@pay_type, bank=@bank ,cash=@cash,visa=@visa,notes=@notes,InvProfit=@InvProfit,Sync=@Sync,paid=@paid\r\n                                              ,EntryID=@EntryID,ExtraVAT=@ExtraVAT,AdditionalCost=@AdditionalCost,InvoiceStatus=@InvoiceStatus ,PriceIncVAT=@PriceIncVAT,PaymentStatus=@PaymentStatus,InvCombinedId=@InvCombinedId,ItemsDiscount=@ItemsDiscount,InvCost=@InvCost,FreeVATSales=@FreeVATSales,InvSum=@InvSum,VATPercent=@VATPercent,CurrencyCode=@CurrencyCode,CloudID=@CloudID,CashCustomerName=@CashCustomerName,CashCustomerMobile=@CashCustomerMobile,TotalWithholdingTax=@TotalWithholdingTax,TableNo=@TableNo,Balance_previews=@Balance_previews where  InvGlobalID=@InvGlobalID";

